import React, { useState, useEffect } from "react"; 
import ProductForm from "./ProductForm";
import ProductList from "./ProductList";
import Dashboard from "./Dashboard";
import RecordSalesForm from "./RecordSalesForm";
import './App.css';

const BACKEND_URL = process.env.REACT_APP_API_URL;

function App() {
  const [products, setProducts] = useState([]);
  const [editingProduct, setEditingProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [activeTab, setActiveTab] = useState("dashboard");

  const sampleSales = [
    { Day: 'monday', total: 1200 },
    { Day: 'tuesday', total: 1500 },
    { Day: 'wednesday', total: 1000 },
    { Day: 'thursday', total: 1800 },
  ];

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const res = await fetch(`${BACKEND_URL}/api/products`);
      if (!res.ok) throw new Error("Failed to fetch products");
      const data = await res.json();
      setProducts(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  const handleProductAdded = (product) => setProducts([...products, product]);
  const handleProductDeleted = (id) => setProducts(products.filter(p => p.id !== id));
  const handleProductUpdated = (updatedProduct) =>
    setProducts(products.map(p => p.id === updatedProduct.id ? updatedProduct : p));

  return (
    <div className="App">
      <h1>Wings Cafe Inventory System</h1>

      {loading && <p>Loading products...</p>}
      {error && <p style={{ color: "red" }}>Error: {error}</p>}

      {!loading && !error && (
        <>
          <button onClick={fetchProducts} className="refresh-btn">🔄 Refresh Products</button>

          {/* Tab Buttons */}
          <div className="tabs">
            <button className={activeTab === "dashboard" ? "active" : ""} onClick={() => setActiveTab("dashboard")}>📊 Dashboard</button>
            <button className={activeTab === "add" ? "active" : ""} onClick={() => setActiveTab("add")}>➕ Add Product</button>
            <button className={activeTab === "list" ? "active" : ""} onClick={() => setActiveTab("list")}>📋 Product List</button>
            <button className={activeTab === "sales" ? "active" : ""} onClick={() => setActiveTab("sales")}>🛒 Record Sale</button>
          </div>

          {/* Tab Content */}
          {activeTab === "dashboard" && <Dashboard products={products} sales={sampleSales} />}
          {activeTab === "add" && (
            <ProductForm
              onProductAdded={handleProductAdded}
              editingProduct={editingProduct}
              onProductUpdated={handleProductUpdated}
              setEditingProduct={setEditingProduct}
            />
          )}
          {activeTab === "list" && (
            <ProductList
              products={products}
              onEdit={setEditingProduct}
              fetchProducts={fetchProducts}
              onDelete={handleProductDeleted}
            />
          )}
          {activeTab === "sales" && <RecordSalesForm />}
        </>
      )}
    </div>
  );
}

export default App;
